import itertools
import math

def gcd(a, b):
    while b:
        a, b = b, a % b
    return a

def gcd_three(a, b, c):
    return gcd(a, gcd(b, c))

def check_good_set(U):
    """Checks if a set U is a good set."""
    n = len(U)
    if n < 3:
        return False

    # Condition 1: GCD of any three distinct elements is 1.
    for a, b, c in itertools.combinations(U, 3):
        if gcd_three(a, b, c) != 1:
            return False

    # Condition 2: For any two distinct elements a, b in U, there exists c in U such that c | ab.
    # Note: The problem phrasing is "there exists another element that is a divisor of their product".
    # Since the set U is finite and we are checking existence, we check for any c in U.
    # If the intent was c != a and c != b, the checks below must be adjusted, but standard phrasing usually means c in U.
    for a, b in itertools.combinations(U, 2):
        product = a * b
        found_divisor = False
        for c in U:
            if product % c == 0:
                found_divisor = True
                break
        if not found_divisor:
            return False

    return True

# Elements are positive integers less than 15, i.e., {1, 2, ..., 14}
elements = list(range(1, 15))
good_sets = []

# Iterate over all possible set sizes from 3 up to 14
for k in range(3, len(elements) + 1):
    for U_tuple in itertools.combinations(elements, k):
        U = list(U_tuple)
        if check_good_set(U):
            good_sets.append(U)

print(f"Found {len(good_sets)} good sets where all elements are < 15.")
# Print the first 10 found sets for inspection
if good_sets:
    print("\nFirst 10 found good sets:")
    for i in range(min(10, len(good_sets))):
        print(f"Set {i+1}: {good_sets[i]}")

# Optional: Check a specific known small candidate set, e.g., {2, 3, 5}
