# # (1, 3): product 3. Divisors in U: 1, 3. Yes.
# # (2, 3): product 6. Divisors in U: 1, 2, 3. Yes.
# # Expected: True
# print(check_good_set([1, 2, 3]))

from math import gcd

def check_gcd_triple(U):
    if len(U) < 3:
        return False

    # Check Condition 1: gcd(u_i, u_j, u_k) = 1 for all distinct triplets
    indices = range(len(U))
    for i in indices:
        for j in indices:
            if i == j: continue
            for k in indices:
                if k == i or k == j: continue

                g = gcd(U[i], gcd(U[j], U[k]))
                if g != 1:
                    return False
    return True

# Test the set U = {6, 10, 15}
U_test = [6, 10, 15]
print(f"Is {U_test} C1 compliant? {check_gcd_triple(U_test)}")

